from openpyxl import load_workbook

# Load the workbook
wb = load_workbook('./initial.xlsx')
ws = wb['Sheet1']

# Get the number of rows
max_row = ws.max_row

# Check if column I header exists, if not add it
header_cell = ws.cell(row=1, column=9)
if header_cell.value is None or header_cell.value == '':
    header_cell.value = "Liabilities & Owner's Equity"

# Calculate Assets (column E = B + C + D) for rows 2 onwards
for row in range(2, max_row + 1):
    current_assets = ws.cell(row=row, column=2).value
    fixed_assets = ws.cell(row=row, column=3).value
    other_assets = ws.cell(row=row, column=4).value

    # Convert to numbers if they're strings
    try:
        current_assets = float(current_assets) if current_assets else 0
    except (ValueError, TypeError):
        current_assets = 0

    try:
        fixed_assets = float(fixed_assets) if fixed_assets else 0
    except (ValueError, TypeError):
        fixed_assets = 0

    try:
        other_assets = float(other_assets) if other_assets else 0
    except (ValueError, TypeError):
        other_assets = 0

    assets = current_assets + fixed_assets + other_assets
    ws.cell(row=row, column=5).value = assets

# Calculate Liabilities & Owner's Equity (column I = F + G + H) for rows 2 onwards
for row in range(2, max_row + 1):
    current_liabilities = ws.cell(row=row, column=6).value
    long_term_liabilities = ws.cell(row=row, column=7).value
    owners_equity = ws.cell(row=row, column=8).value

    # Convert to numbers if they're strings
    try:
        current_liabilities = float(current_liabilities) if current_liabilities else 0
    except (ValueError, TypeError):
        current_liabilities = 0

    try:
        long_term_liabilities = float(long_term_liabilities) if long_term_liabilities else 0
    except (ValueError, TypeError):
        long_term_liabilities = 0

    try:
        owners_equity = float(owners_equity) if owners_equity else 0
    except (ValueError, TypeError):
        owners_equity = 0

    liabilities_equity = current_liabilities + long_term_liabilities + owners_equity
    ws.cell(row=row, column=9).value = liabilities_equity

# Apply accounting number format to all numeric cells in columns B through I
accounting_format = '_($* #,##0_);_($* (#,##0);_($* "-"_);_(@_)'

for row in range(2, max_row + 1):
    for col in range(2, 10):  # Columns B through I (2-9)
        cell = ws.cell(row=row, column=col)
        if cell.value is not None:
            try:
                # Ensure value is numeric
                cell.value = float(cell.value)
                cell.number_format = accounting_format
            except (ValueError, TypeError):
                pass

# Save the workbook
wb.save('./output.xlsx')
